def luckyNumberGame(nums, a, b):
	bobMoves = aliceMoves = commonMoves = 0
	for num in nums:
		if num % a == 0 and num % b == 0:
			commonMoves += 1
		elif num % a == 0:
			bobMoves += 1
		elif num % b == 0:
			aliceMoves += 1
	if commonMoves:
		bobMoves += 1
	if bobMoves > aliceMoves:
		return 'BOB'
	else:
		return 'ALICE'
